        super(reservations);
        this.taxPerGuestNight = taxPerGuestNight;
    }

    @Override
    public String name() { return "tourism-tax"; }

    @Override
    protected List<String> columns() {
        return List.of("reservation", "room", "check_in", "check_out", "guests", "nights", "tax");
